-- Permenhut No. 6 Tahun 2026 — regulatory_rules table
-- Encoded in Indonesian per request. Source: full 65-pasal regulation text.

CREATE TABLE IF NOT EXISTS regulatory_rules (
  rule_id TEXT PRIMARY KEY,
  pasal TEXT,
  kategori TEXT,
  ringkasan TEXT,
  jangka_waktu_atau_tenggat TEXT,
  mulai_berlaku DATE,
  deadline_absolut DATE,
  pihak_terkait TEXT,
  catatan_gluribridge TEXT
);

