INSERT INTO regulatory_rules (rule_id, pasal, kategori, ringkasan, jangka_waktu_atau_tenggat, mulai_berlaku, deadline_absolut, pihak_terkait, catatan_gluribridge) VALUES ('R001', '-', 'Metadata Peraturan', 'Peraturan Menteri Kehutanan RI Nomor 6 Tahun 2026 tentang Tata Cara Perdagangan Karbon Melalui Offset Emisi Gas Rumah Kaca Sektor Kehutanan. Ditetapkan di Jakarta 6 April 2026, diundangkan 13 April 2026 (Berita Negara RI Tahun 2026 Nomor 238). Mencabut Permen LHK No. 7 Tahun 2023.', '-', '2026-04-13', NULL, 'Semua pelaku perdagangan karbon sektor kehutanan', 'Dasar hukum utama untuk compliance badge GluriBridge.');
INSERT INTO regulatory_rules (rule_id, pasal, kategori, ringkasan, jangka_waktu_atau_tenggat, mulai_berlaku, deadline_absolut, pihak_terkait, catatan_gluribridge) VALUES ('R002', 'Pasal 65', 'Mulai Berlaku', 'Peraturan Menteri ini mulai berlaku pada tanggal diundangkan.', '-', '2026-04-13', NULL, 'Semua', 'effective_date acuan untuk semua tenggat turunan (terutama Pasal 61).');
INSERT INTO regulatory_rules (rule_id, pasal, kategori, ringkasan, jangka_waktu_atau_tenggat, mulai_berlaku, deadline_absolut, pihak_terkait, catatan_gluribridge) VALUES ('R003', 'Pasal 6(1)', 'Subjek / Pelaku Usaha yang Berhak', 'Pelaku Usaha yang dapat melakukan Perdagangan Karbon meliputi: (a) pemegang PBPH & pemegang hak pengelolaan; (b) pemegang Persetujuan Pengelolaan Perhutanan Sosial; (c) masyarakat hukum adat pemegang penetapan status hutan adat; (d) pemegang registrasi hutan hak; (e) pemegang PB-PJL Karbon.', '-', NULL, NULL, 'Pelaku usaha sektor kehutanan (5 kategori)', '5 kategori ini sebaiknya jadi nilai baku field land_rights_flag pada unified candidate record, menggantikan kategori generik yang dipakai sebelumnya.');
INSERT INTO regulatory_rules (rule_id, pasal, kategori, ringkasan, jangka_waktu_atau_tenggat, mulai_berlaku, deadline_absolut, pihak_terkait, catatan_gluribridge) VALUES ('R004', 'Pasal 6(2)', 'Kewajiban Pendampingan', 'Pelaku Usaha kategori (b) Perhutanan Sosial, (c) masyarakat hukum adat, dan (d) hutan hak wajib didampingi oleh mitra/pendamping yang teregistrasi.', '-', NULL, NULL, 'Kategori b, c, d dari Pasal 6(1)', 'Sinyal need-detection: kandidat kategori ini tanpa pendamping terdaftar belum siap PoC — perlu pendamping dulu, bukan langsung kontak Gluri.');
INSERT INTO regulatory_rules (rule_id, pasal, kategori, ringkasan, jangka_waktu_atau_tenggat, mulai_berlaku, deadline_absolut, pihak_terkait, catatan_gluribridge) VALUES ('R005', 'Pasal 9(1)', 'Cakupan Wilayah / Objek Karbon', 'Karbon yang dapat diperdagangkan berasal dari aksi mitigasi di: (a) kawasan hutan produksi tetap/konversi & blok pemanfaatan hutan lindung yang telah berizin; (b) zona KPA & Taman Buru yang belum berizin; (c) hutan adat; (d) hutan hak; (e) hutan negara bukan kawasan hutan.', '-', NULL, NULL, 'Semua kategori Pasal 6(1)', 'Dipakai untuk menilai apakah lokasi kandidat (dari SRUK/BRWA/Verra) memenuhi syarat objek karbon sektor kehutanan.');
INSERT INTO regulatory_rules (rule_id, pasal, kategori, ringkasan, jangka_waktu_atau_tenggat, mulai_berlaku, deadline_absolut, pihak_terkait, catatan_gluribridge) VALUES ('R006', 'Pasal 10', 'Syarat Dasar', 'Untuk melakukan Perdagangan Karbon, Pelaku Usaha harus memiliki Unit Karbon berupa SPE GRK (skema domestik, rekomendasi Menteri Kehutanan) atau non-SPE GRK (standar internasional, persetujuan Menteri).', '-', NULL, NULL, 'Semua Pelaku Usaha', 'Memetakan langsung ke field SRUK dram/lcam/verified_carbon_amount — proyek tanpa Unit Karbon berarti masih pra-transaksi (kandidat PoC yang relevan bagi Gluri).');
INSERT INTO regulatory_rules (rule_id, pasal, kategori, ringkasan, jangka_waktu_atau_tenggat, mulai_berlaku, deadline_absolut, pihak_terkait, catatan_gluribridge) VALUES ('R007', 'Pasal 11-14', 'Prosedur & Tenggat Administratif', 'Permohonan pencatatan DRAM diajukan melalui SRUK. Pemeriksaan kelengkapan dokumen DRAM oleh Menteri paling lama 5 hari kerja sejak permohonan diterima. Jika dinyatakan tidak lengkap, pemohon harus melengkapi dalam 5 hari kerja sejak notifikasi diterima.', '5 hari kerja (pemeriksaan) + 5 hari kerja (perbaikan jika kurang lengkap)', NULL, NULL, 'Pelaku usaha pemohon pencatatan DRAM', 'SLA acuan untuk menilai registration_momentum — proyek yang macet di tahap ini lebih dari ~10 hari kerja layak diberi flag anomali pada need-detection.');
INSERT INTO regulatory_rules (rule_id, pasal, kategori, ringkasan, jangka_waktu_atau_tenggat, mulai_berlaku, deadline_absolut, pihak_terkait, catatan_gluribridge) VALUES ('R008', 'Pasal 15-17', 'Prosedur & Tenggat Administratif', 'Permohonan rekomendasi penerbitan SPE GRK harus disertai laporan validasi DRAM, pelaksanaan sesuai DRAM, verifikasi capaian, hasil verifikasi, dan data pendukung. Pemeriksaan kelengkapan dokumen paling lama 14 hari kerja sejak dokumen dinyatakan lengkap; turut diperiksa riwayat kepatuhan dan sanksi administratif.', '14 hari kerja', NULL, NULL, 'Pelaku usaha pemohon rekomendasi SPE GRK', 'Setara tahap SRUK ''DATA VALIDASI''/''DATA VERIFIKASI'' — proyek di tahap ini >14 hari kerja tanpa keputusan layak ditandai stalled.');
INSERT INTO regulatory_rules (rule_id, pasal, kategori, ringkasan, jangka_waktu_atau_tenggat, mulai_berlaku, deadline_absolut, pihak_terkait, catatan_gluribridge) VALUES ('R009', 'Pasal 16(4)', 'Kewenangan Pemeriksa', 'Pemeriksaan kelengkapan dokumen dilakukan oleh pejabat berbeda menurut kategori pelaku usaha: (a) bidang pengelolaan hutan lestari untuk pemegang PBPH/hak pengelolaan; (b) bidang perhutanan sosial untuk pemegang Persetujuan PS/hutan adat/hutan hak; (c) bidang konservasi SDA & ekosistem untuk pemegang PB-PJL Karbon.', '-', NULL, NULL, 'Internal Kementerian Kehutanan', 'Menentukan instansi/unit Kementerian mana yang relevan dihubungi per tipe kandidat — dipakai untuk field responsible_agency di dossier.');
INSERT INTO regulatory_rules (rule_id, pasal, kategori, ringkasan, jangka_waktu_atau_tenggat, mulai_berlaku, deadline_absolut, pihak_terkait, catatan_gluribridge) VALUES ('R010', 'Pasal 24', 'Masa Berlaku Persetujuan', 'Persetujuan Menteri untuk penerbitan non-SPE GRK oleh standar internasional (mis. Verra) berlaku 6 (enam) bulan.', '6 bulan sejak persetujuan terbit', NULL, NULL, 'Pelaku usaha dengan skema sertifikasi internasional', 'Relevan untuk kandidat terdaftar di Verra yang juga mengajukan SRUK — persetujuan Menteri mereka bisa kedaluwarsa, sinyal urgensi tambahan.');
INSERT INTO regulatory_rules (rule_id, pasal, kategori, ringkasan, jangka_waktu_atau_tenggat, mulai_berlaku, deadline_absolut, pihak_terkait, catatan_gluribridge) VALUES ('R011', 'Pasal 26(3)', 'Prosedur & Tenggat Administratif', 'Rekomendasi Otorisasi & Corresponding Adjustment untuk perdagangan karbon luar negeri disampaikan kepada pemohon paling lambat 7 (tujuh) hari kerja sejak permohonan diterima.', '7 hari kerja', NULL, NULL, 'Pelaku usaha yang berdagang karbon ke luar negeri', 'Relevan untuk kandidat yang berniat menjual unit karbon lintas negara (mis. ke Korea) — proses ini lebih cepat dari tahap DRAM.');
INSERT INTO regulatory_rules (rule_id, pasal, kategori, ringkasan, jangka_waktu_atau_tenggat, mulai_berlaku, deadline_absolut, pihak_terkait, catatan_gluribridge) VALUES ('R012', 'Pasal 28', 'Kewajiban Substantif (Safeguard)', 'Pelaku Usaha wajib menerapkan prinsip perlindungan sosial, lingkungan, dan tata kelola: kepatuhan hukum, transparansi tata kelola hutan, hak masyarakat adat & lokal, efektivitas partisipasi, konservasi keanekaragaman hayati, mitigasi risiko-balik (reversal), dan pengurangan pengalihan emisi (leakage). Wajib melapor pemenuhan prinsip ini kepada Menteri.', '-', NULL, NULL, 'Semua Pelaku Usaha', 'Sumber utama kriteria ''hak masyarakat adat'' yang tumpang tindih dengan data BRWA — jika kandidat berada di/dekat wilayah adat terdaftar BRWA, laporan safeguard ini seharusnya ada di program_documents SRUK.');
INSERT INTO regulatory_rules (rule_id, pasal, kategori, ringkasan, jangka_waktu_atau_tenggat, mulai_berlaku, deadline_absolut, pihak_terkait, catatan_gluribridge) VALUES ('R013', 'Pasal 41-45', 'Validasi & Verifikasi', 'Setiap Unit Karbon wajib melalui validasi dan verifikasi oleh lembaga independen berbadan hukum, terakreditasi (komite akreditasi nasional untuk skema SRUK, atau lembaga akreditasi internasional untuk skema internasional), dan mempekerjakan tenaga kerja Indonesia berkualifikasi. Validasi memeriksa baseline & additionality; verifikasi memeriksa realisasi capaian vs rencana.', '-', NULL, NULL, 'Lembaga Validasi dan Verifikasi (LVV) independen', 'Memetakan langsung ke field SRUK validators.lvv_dram / validators.lvv_lcam dan tahap workflow DATA VALIDASI/DATA VERIFIKASI.');
INSERT INTO regulatory_rules (rule_id, pasal, kategori, ringkasan, jangka_waktu_atau_tenggat, mulai_berlaku, deadline_absolut, pihak_terkait, catatan_gluribridge) VALUES ('R014', 'Pasal 54', 'Kewajiban Pelaporan Berkala', 'Penanggung jawab wajib menyampaikan laporan pelaksanaan Perdagangan Karbon secara elektronik kepada Menteri (tembusan Gubernur/Bupati/KPH/UPT), memuat: pelaksanaan perdagangan, peran serta masyarakat, pelaksanaan pembagian manfaat, dan tindak lanjut pengaduan masyarakat.', 'Berkala (frekuensi rinci tidak disebutkan eksplisit di luar evaluasi tahunan Pasal 55)', NULL, NULL, 'Semua penanggung jawab Aksi Mitigasi', 'Dasar hukum kewajiban pelaporan berkelanjutan — proyek yang lama tidak memperbarui program_documents di SRUK berpotensi melanggar pasal ini (sinyal need-detection tambahan).');
INSERT INTO regulatory_rules (rule_id, pasal, kategori, ringkasan, jangka_waktu_atau_tenggat, mulai_berlaku, deadline_absolut, pihak_terkait, catatan_gluribridge) VALUES ('R015', 'Pasal 55(4)', 'Evaluasi Berkala', 'Evaluasi kinerja Perdagangan Karbon dilaksanakan paling sedikit 1 (satu) kali dalam 1 (satu) tahun.', 'Minimal 1x per tahun', NULL, NULL, 'Menteri (pejabat pimpinan tinggi madya terkait)', 'Konteks makro, bukan tenggat per-kandidat.');
INSERT INTO regulatory_rules (rule_id, pasal, kategori, ringkasan, jangka_waktu_atau_tenggat, mulai_berlaku, deadline_absolut, pihak_terkait, catatan_gluribridge) VALUES ('R016', 'Pasal 61', 'Ketentuan Peralihan / TENGGAT WAJIB LAPOR', 'Sejak Peraturan Menteri ini berlaku: (a) penanggung jawab yang telah memasuki tahap validasi DRAM/DPP, pelaksanaan aksi mitigasi, verifikasi capaian, atau pelaporan capaian; ATAU (b) penanggung jawab yang telah memiliki Unit Karbon namun belum bertransaksi — wajib melaporkan kegiatannya kepada Menteri paling lambat 6 (enam) bulan sejak Peraturan Menteri diundangkan, dan dapat segera mengajukan permohonan rekomendasi/persetujuan Menteri.', '6 bulan sejak 13 April 2026', NULL, '2026-10-13', 'Proyek yang sudah berjalan sebelum Permenhut 6/2026 berlaku (transisi)', 'SUMBER TENGGAT UNTUK COMPLIANCE BADGE. Proyek SRUK stage >= 2 (DATA TEKNIS) yang dibuat sebelum 13 April 2026 dan belum lapor ke Menteri berisiko RED badge setelah 13 Oktober 2026.');
INSERT INTO regulatory_rules (rule_id, pasal, kategori, ringkasan, jangka_waktu_atau_tenggat, mulai_berlaku, deadline_absolut, pihak_terkait, catatan_gluribridge) VALUES ('R017', 'Pasal 63', 'Ketentuan Peralihan', 'Peta jalan Perdagangan Karbon (roadmap nasional) ditetapkan paling lambat 1 (satu) tahun sejak Peraturan Menteri ini mulai berlaku.', '1 tahun sejak 13 April 2026', NULL, '2027-04-13', 'Menteri (bukan pelaku usaha individual)', 'Konteks makro/kebijakan nasional, tidak dipakai untuk badge per-kandidat.');
INSERT INTO regulatory_rules (rule_id, pasal, kategori, ringkasan, jangka_waktu_atau_tenggat, mulai_berlaku, deadline_absolut, pihak_terkait, catatan_gluribridge) VALUES ('R018', 'Pasal 64', 'Pencabutan Regulasi Sebelumnya', 'Peraturan Menteri LHK Nomor 7 Tahun 2023 tentang Tata Cara Perdagangan Karbon Sektor Kehutanan dicabut dan dinyatakan tidak berlaku.', '-', NULL, NULL, 'Semua', 'Proyek SRUK lama yang mereferensikan Permen 7/2023 harus dibaca dalam konteks Permenhut 6/2026 ini.');
INSERT INTO regulatory_rules (rule_id, pasal, kategori, ringkasan, jangka_waktu_atau_tenggat, mulai_berlaku, deadline_absolut, pihak_terkait, catatan_gluribridge) VALUES ('R019', 'Pasal 60', 'Ketentuan Peralihan', 'Sampai SRUK beroperasi secara menyeluruh, pencatatan DRAM/DPP dilakukan melalui sistem elektronik lain di Kementerian, oleh pejabat yang ditugaskan Menteri.', '-', NULL, NULL, 'Kementerian Kehutanan (internal)', 'Menjelaskan mengapa proyek versi lama bisa punya data tidak lengkap/berbeda format di SRUK — konsisten dengan variasi skema field yang sudah ditemukan antara sampel REG-11 (kehutanan) dan REG-10 (limbah).');
INSERT INTO regulatory_rules (rule_id, pasal, kategori, ringkasan, jangka_waktu_atau_tenggat, mulai_berlaku, deadline_absolut, pihak_terkait, catatan_gluribridge) VALUES ('R020', 'Pasal 18', 'Prosedur & Kewenangan Antar-Kementerian', 'Pelaku Usaha yang telah mendapat rekomendasi penerbitan SPE GRK dari Menteri Kehutanan dapat mengajukan permohonan PENERBITAN SPE GRK kepada menteri yang menyelenggarakan urusan pemerintahan di bidang perlindungan dan pengelolaan lingkungan hidup (Menteri LH). Tata cara permohonan & penerbitan Unit Karbon mengikuti ketentuan peraturan perundang-undangan lain di luar Permenhut ini.', '-', NULL, NULL, 'Pelaku usaha yang sudah punya rekomendasi SPE GRK', 'PENTING: rekomendasi = wewenang Menteri Kehutanan; penerbitan final = wewenang Menteri LH. Dua kementerian berbeda dalam satu alur — field responsible_agency di dossier harus membedakan tahap rekomendasi vs tahap penerbitan.');
INSERT INTO regulatory_rules (rule_id, pasal, kategori, ringkasan, jangka_waktu_atau_tenggat, mulai_berlaku, deadline_absolut, pihak_terkait, catatan_gluribridge) VALUES ('R021', 'Pasal 19', 'Pihak Pembeli / Skema Transaksi', 'Pelaku Usaha yang telah memiliki SPE GRK dapat melakukan Perdagangan Karbon melalui Offset Emisi GRK kepada: (a) penanggung jawab yang emisinya melampaui batas atas dalam 1 periode (pasar kepatuhan/compliance); (b) Pelaku Usaha yang melakukan Offset secara sukarela (pasar sukarela/voluntary); dan/atau (c) masyarakat.', '-', NULL, NULL, 'Pelaku usaha pemegang SPE GRK', 'Menandai apakah target pembeli kandidat adalah pasar kepatuhan atau pasar sukarela — bisa memengaruhi urgensi & jenis mitra yang relevan bagi kandidat.');
INSERT INTO regulatory_rules (rule_id, pasal, kategori, ringkasan, jangka_waktu_atau_tenggat, mulai_berlaku, deadline_absolut, pihak_terkait, catatan_gluribridge) VALUES ('R022', 'Pasal 20', 'Prosedur DPP (Jalur non-SPE/Internasional)', 'Pelaku Usaha yang ingin unit karbonnya diterbitkan oleh standar internasional (mis. Verra) harus mengajukan permohonan PERSETUJUAN (bukan rekomendasi) kepada Menteri, melalui dua tahap: (a) pencatatan DPP — Dokumen Perencanaan Proyek, padanan DRAM untuk skema internasional; dan (b) permohonan persetujuan penerbitan non-SPE GRK.', '-', NULL, NULL, 'Pelaku usaha dengan skema sertifikasi internasional (mis. proyek terdaftar Verra)', 'GAP YANG DITUTUP. DPP adalah padanan DRAM untuk kandidat berskema internasional. Field SRUK ''dram'' akan kosong untuk kandidat semacam ini secara SAH (bukan gap) — unified candidate record perlu field dpp terpisah dari dram, dan need-detection tidak boleh menandai ''tidak ada DRAM'' sebagai kekurangan otomatis untuk kandidat sumber Verra.');
INSERT INTO regulatory_rules (rule_id, pasal, kategori, ringkasan, jangka_waktu_atau_tenggat, mulai_berlaku, deadline_absolut, pihak_terkait, catatan_gluribridge) VALUES ('R023', 'Pasal 21', 'Prosedur & Tenggat Administratif (DPP)', 'Tata cara pencatatan DPP mengikuti (mutatis mutandis) tata cara pencatatan DRAM pada Pasal 12-14: DPP harus memuat rencana aksi mitigasi, usulan aksi, metodologi, analisis dampak lingkungan & pembangunan berkelanjutan, konsultasi publik, dan data pendukung. Pemeriksaan kelengkapan paling lama 5 hari kerja; perbaikan jika kurang lengkap paling lama 5 hari kerja sejak notifikasi.', '5 hari kerja (pemeriksaan) + 5 hari kerja (perbaikan jika kurang lengkap)', NULL, NULL, 'Pelaku usaha pemohon pencatatan DPP', 'Aturan ''kembar'' dari R007 (DRAM) — SLA identik, berlaku untuk jalur DPP/internasional.');
INSERT INTO regulatory_rules (rule_id, pasal, kategori, ringkasan, jangka_waktu_atau_tenggat, mulai_berlaku, deadline_absolut, pihak_terkait, catatan_gluribridge) VALUES ('R024', 'Pasal 22', 'Prosedur DPP (Jalur non-SPE/Internasional)', 'Permohonan persetujuan penerbitan non-SPE GRK harus disertai laporan pemenuhan: validasi DPP oleh lembaga validasi independen, pelaksanaan sesuai DPP, verifikasi capaian oleh lembaga verifikasi independen, laporan hasil verifikasi, dan data pendukung (sama seperti Pasal 12(2)).', '-', NULL, NULL, 'Pelaku usaha pemohon persetujuan non-SPE GRK', 'Padanan R008 (Pasal 15, syarat rekomendasi SPE GRK) tapi untuk jalur non-SPE/internasional.');
INSERT INTO regulatory_rules (rule_id, pasal, kategori, ringkasan, jangka_waktu_atau_tenggat, mulai_berlaku, deadline_absolut, pihak_terkait, catatan_gluribridge) VALUES ('R025', 'Pasal 23', 'Prosedur & Tenggat Administratif (DPP)', 'Pemeriksaan kelengkapan dokumen permohonan non-SPE GRK mengikuti (mutatis mutandis) ketentuan pemeriksaan SPE GRK pada Pasal 15-19 — termasuk tenggat 14 hari kerja pemeriksaan kelengkapan dan pemeriksaan riwayat kepatuhan/sanksi administratif. Persetujuan yang terbit berlaku 6 bulan (lihat R010, Pasal 24).', '14 hari kerja', NULL, NULL, 'Pelaku usaha pemohon persetujuan non-SPE GRK', 'Aturan ''kembar'' dari R008 (SPE GRK) — SLA identik, berlaku untuk jalur DPP/internasional. Hasil akhirnya adalah Persetujuan Menteri yang masa berlakunya diatur di R010.');
